package com.example.meallens.data;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

/** Result of analysing a meal photo: dish name, confidence and the ingredient list. */
public class MealAnalysis implements Serializable {
    private static final long serialVersionUID = 1L;

    public final String title;
    public final String titleAr;
    public final double confidence;
    public final ArrayList<DetectedItem> items;

    /** Plain-language description generated by the model. */
    public String summary = "";
    /** Optional caption the user typed before uploading the photo. */
    public String caption = "";
    /** Model-provided health observations; the app also derives its own flags. */
    public ArrayList<Flag> aiFlags = new ArrayList<>();

    public MealAnalysis(String title, String titleAr, double confidence, List<DetectedItem> items) {
        this.title = title;
        this.titleAr = titleAr;
        this.confidence = confidence;
        this.items = new ArrayList<>(items);
    }

    public MealAnalysis(String title, String titleAr, double confidence, List<DetectedItem> items,
                        String summary, String caption, List<Flag> aiFlags) {
        this(title, titleAr, confidence, items);
        this.summary = summary == null ? "" : summary;
        this.caption = caption == null ? "" : caption;
        if (aiFlags != null) this.aiFlags = new ArrayList<>(aiFlags);
    }

    public int totalGrams() {
        int g = 0;
        for (DetectedItem it : items) g += it.grams;
        return g;
    }
}
